mapper.codeEditorJavascript:
const d=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const p=n=>String(n).padStart(2,'0');
return {today:d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())};

const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const norm=s=>String(s==null?'':s).replace(/\s+/g,' ').trim();
const dg=s=>String(s==null?'':s).replace(/\D/g,'');
const rep=norm(input.rep);
let phone='';
for(const r of arr(input.targets)){ if(r&&norm(r[0])===rep) phone=dg(r[1]).slice(-9); }
let warn='';
if(phone.length!==9){ phone='544604246'; warn='לא מצאתי את המספר של הנציג ('+rep+'). ההודעה בשבילו:\n\n'; }
const st=norm(input.status);
const why = st==='ממתין' ? 'הבקשה עדיין ממתינה לתשובה מהחברה' : (st==='נדחה' ? 'הבקשה נדחתה' : 'הבקשה לא אושרה');
const msg=warn+'בוקר טוב '+rep.split(' ')[0]+'\nביקשת להקדים להיום את '+norm(input.cname)+' (מספר '+norm(input.cnum)+')'+(norm(input.slot)?' ('+norm(input.slot)+')':'')+', אבל '+why+', אז זה עדיין לא הוקדם.\n\nאם רוצים להתקין היום, שולחים בקשה בוואטסאפ למשווקים יס (050-2552817):\n1. הודעה ראשונה: "הקדמת לקוח חדש"\n2. אחריה הודעה אחת עם: מספר לקוח, כתובת, כמות ממירים, התקנת סיב (כן/לא), סיב קיים (כן/לא/לא רלוונטי), חלון זמן מועדף ושם הנציג.';
return {chatId:'972'+phone+'@c.us', message:msg};
